/**
 * Speed-report drift gate (run in CI via `npm run bench:check`).
 *
 * `docs/speed-report.md` is generated by `npm run bench` and silently went
 * stale once when the search changed. This fails when any benchmark-relevant
 * source file changed in the diff against the base but the report did not.
 *
 * The base commit comes from `BENCH_BASE_SHA` (CI passes the PR base SHA, or
 * the previous commit on a push to main). With no base, or with git history
 * unavailable, the check skips rather than failing.
 */
import { execFileSync } from 'child_process';

/** Changing any of these invalidates the numbers in the report. */
const WATCHED = [
  'src/optimizer/search.ts',
  'src/optimizer/score.ts',
  'src/optimizer/benchmark.ts',
];
const REPORT = 'docs/speed-report.md';

const base = process.env.BENCH_BASE_SHA?.trim();
if (!base) {
  console.log('bench:check — no BENCH_BASE_SHA, skipping.');
  process.exit(0);
}

let changed: string[];
try {
  changed = execFileSync('git', ['diff', '--name-only', `${base}...HEAD`], {
    encoding: 'utf-8',
  })
    .split('\n')
    .map((l) => l.trim())
    .filter(Boolean);
} catch {
  console.log(
    `bench:check — cannot diff against ${base} (shallow clone?), skipping.`,
  );
  process.exit(0);
}

const touched = WATCHED.filter((f) => changed.includes(f));
if (touched.length > 0 && !changed.includes(REPORT)) {
  console.error(
    `bench:check failed — ${touched.join(', ')} changed but ${REPORT} did not.\n` +
      `The report's numbers are generated: run \`npm run bench\` and commit ${REPORT}.`,
  );
  process.exit(1);
}

console.log('bench:check — ok.');
